const items = $input.all();

// ==================== RÉCUPÉRER urlAAP DEPUIS "Code in JavaScript17" ====================
let traitementItems = [];
try {
  const js2Item = $('Code in JavaScript17').first();
  traitementItems = [js2Item];
  console.log(`✓ Item trouvé dans "Code in JavaScript17"`);
  console.log(`urlAAP=${js2Item.json?.urlAAP}, cle_dce=${js2Item.json?.cle_dce}`);
} catch(e) {
