}

// ==================== SÉPARER LES TYPES D'ITEMS ====================
const pertinenceItems = [];
const pdfItems = [];
const offreItems = [];

for (const item of items) {
  const j = item.json || {};

  // Détection pertinence : contient les champs de scoring
  if (typeof j.text === 'string' && (
    j.text.includes('savoir_faire_resultat') ||
    j.text.includes('savoir_faire_note')
  )) {
    pertinenceItems.push(item);
    continue;
  }

  // Détection PDF : a numpages
  if (j.numpages !== undefined) {
    pdfItems.push(item);
    continue;
  }

  // Détection offre : JSON avec name, date_deadline, etc.
  if (typeof j.text === 'string' && (
    j.text.trim().startsWith('[') ||
    j.text.trim().startsWith('{') ||
    j.text.includes('date_deadline') ||
    j.text.includes('"name"')
  )) {
    offreItems.push(item);
    continue;
  }

  // Item déjà parsé
  if (j.name && (j.date_deadline || j.company_name)) {
    offreItems.push(item);
  }
}

// Items avec cle_dce → traitement source
const sourceItems = items.filter(i => i.json?.cle_dce !== undefined);

console.log(`Pertinence: ${pertinenceItems.length}, PDF: ${pdfItems.length}, Offres: ${offreItems.length}, Source: ${sourceItems.length}`);

// ==================== PARSERS ====================

function parsePertinence(item) {
  try {
    const raw = item?.json?.text || "";

    let cleaned = raw
      .replace(/```json\s*/gi, '')
      .replace(/```\s*/gi, '')
      .replace(/\\n/g, '\n')
      .replace(/\\"/g, '"')
      .trim();

    if (cleaned.startsWith('"') && cleaned.endsWith('"')) {
      cleaned = cleaned.slice(1, -1);
    }

    console.log('Pertinence nettoyée:', cleaned.substring(0, 100) + '...');

    const parsed = JSON.parse(cleaned);
    const data = Array.isArray(parsed) ? parsed[0] : parsed;

    return {
      savoir_faire_resultat: data.savoir_faire_resultat || "",
      savoir_faire_note: Number(data.savoir_faire_note) || 0,
      potentiel_client_resultat: data.potentiel_client_resultat || "",
      potentiel_client_note: Number(data.potentiel_client_note) || 0,
      chiffre_affaires_resultat: data.chiffre_affaires_resultat || "",
      chiffre_affaires_note: Number(data.chiffre_affaires_note) || 0,
      duree_recurence_resultat: data.duree_recurence_resultat || "",
      duree_recurence_note: Number(data.duree_recurence_note) || 0,
      delai_reponse_resultat: data.delai_reponse_resultat || "",
      delai_reponse_note: Number(data.delai_reponse_note) || 0,
    };

  } catch(e) {
    console.log('❌ Erreur parsing pertinence:', e.message);
    console.log('Raw text:', item?.json?.text?.substring(0, 200));
    return {
      savoir_faire_resultat: "",
      savoir_faire_note: 0,
      potentiel_client_resultat: "",
      potentiel_client_note: 0,
      chiffre_affaires_resultat: "",
      chiffre_affaires_note: 0,
      duree_recurence_resultat: "",
      duree_recurence_note: 0,
      delai_reponse_resultat: "",
      delai_reponse_note: 0,
    };
  }
}

function parseOffre(item) {
  try {
    const raw = item?.json?.text || "";
    const j = item?.json || {};

    if (j.name && (j.date_deadline || j.company_name)) {
      return j;
    }

    let cleaned = raw
      .replace(/\\n/g, '\n')
      .replace(/\\"/g, '"')
      .trim();

    if (cleaned.startsWith('"') && cleaned.endsWith('"')) {
      cleaned = cleaned.slice(1, -1);
    }

    const jsonStart = cleaned.indexOf('[');
    const jsonEnd = cleaned.lastIndexOf(']') + 1;

    if (jsonStart !== -1 && jsonEnd > jsonStart) {
      const jsonStr = cleaned.substring(jsonStart, jsonEnd);
      const parsed = JSON.parse(jsonStr);
      return Array.isArray(parsed) ? parsed[0] : parsed;
    }

    return JSON.parse(cleaned);

  } catch(e) {
    console.log('❌ Erreur parsing offre:', e.message);
    return item?.json || {};
  }
}

