// ==================== FONCTION GÉNÉRATION PDF ====================
function sanitizePdf(str) {
  return str
    .substring(0, 100)
    .replace(/\\/g, '\\\\')
    .replace(/\(/g, '\\(')
    .replace(/\)/g, '\\)')
    .replace(/é|è|ê|ë/g, 'e').replace(/É|È|Ê/g, 'E')
    .replace(/à|â|ä/g, 'a').replace(/À|Â/g, 'A')
    .replace(/î|ï/g, 'i').replace(/Î/g, 'I')
    .replace(/ô|ö/g, 'o').replace(/Ô/g, 'O')
    .replace(/ù|û|ü/g, 'u').replace(/Ù|Û/g, 'U')
    .replace(/ç/g, 'c').replace(/Ç/g, 'C')
    .replace(/œ/g, 'oe').replace(/Œ/g, 'OE')
    .replace(/«|»/g, '"').replace(/–|—/g, '-')
    .replace(/[']/g, "'")
    .replace(/[^\x20-\x7E]/g, '?');
}

function generatePdfFromText(texte) {
  const lignes = texte
    .split('\n')
    .map(l => l.trim())
    .filter(l => l.length > 0)
    .slice(0, 300);

  const LINES_PER_PAGE = 55;
  const pageContents = [];
  for (let p = 0; p < lignes.length; p += LINES_PER_PAGE) {
    const pageLignes = lignes.slice(p, p + LINES_PER_PAGE);
    const content = pageLignes.map((ligne, idx) => {
      const y = 800 - (idx * 14);
      return `BT /F1 9 Tf 30 ${y} Td (${sanitizePdf(ligne)}) Tj ET`;
    }).join('\n');
    pageContents.push(content);
  }

  const parts = [];
  let pos = 0;
  const header = '%PDF-1.4\n';
  pos = Buffer.byteLength(header, 'latin1');

  const addPart = (str) => {
    pos += Buffer.byteLength(str, 'latin1');
    parts.push(str);
  };

  pageContents.forEach((content, pi) => {
    const len = Buffer.byteLength(content + '\n', 'latin1');
    addPart(`${pi + 1} 0 obj\n<< /Length ${len} >>\nstream\n${content}\nendstream\nendobj\n`);
  });

  const fontNum = pageContents.length + 1;
  addPart(`${fontNum} 0 obj\n<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>\nendobj\n`);

  const pageNums = pageContents.map((_, pi) => fontNum + 1 + pi);
  pageNums.forEach((num, pi) => {
    addPart(`${num} 0 obj\n<< /Type /Page /Parent ${fontNum + 1 + pageContents.length} 0 R /MediaBox [0 0 595 842] /Contents ${pi + 1} 0 R /Resources << /Font << /F1 ${fontNum} 0 R >> >> >>\nendobj\n`);
  });

  const pagesNum = fontNum + 1 + pageContents.length;
  addPart(`${pagesNum} 0 obj\n<< /Type /Pages /Kids [${pageNums.map(n => `${n} 0 R`).join(' ')}] /Count ${pageNums.length} >>\nendobj\n`);

  const catalogNum = pagesNum + 1;
  addPart(`${catalogNum} 0 obj\n<< /Type /Catalog /Pages ${pagesNum} 0 R >>\nendobj\n`);

  let pdfStr = header + parts.join('');
  const xrefPos = Buffer.byteLength(pdfStr, 'latin1');

  let xref = `xref\n0 ${parts.length + 1}\n`;
  xref += `0000000000 65535 f \n`;
  let cumOffset = Buffer.byteLength(header, 'latin1');
  parts.forEach(part => {
    xref += `${String(cumOffset).padStart(10, '0')} 00000 n \n`;
    cumOffset += Buffer.byteLength(part, 'latin1');
  });

  pdfStr += xref;
  pdfStr += `trailer\n<< /Size ${parts.length + 1} /Root ${catalogNum} 0 R >>\nstartxref\n${xrefPos}\n%%EOF\n`;

  return Buffer.from(pdfStr, 'latin1').toString('base64');
}

// ==================== CONSTRUIRE UN LEAD PAR OFFRE ====================
const nbOffres = Math.max(pertinenceItems.length, offreItems.length);
const results = [];

for (let i = 0; i < nbOffres; i++) {

  // --- Pertinence ---
  const pertinenceRaw = parsePertinence(pertinenceItems[i]);

  const notesArr = [
    pertinenceRaw.savoir_faire_note,
    pertinenceRaw.potentiel_client_note,
    pertinenceRaw.chiffre_affaires_note,
    pertinenceRaw.duree_recurence_note,
    pertinenceRaw.delai_reponse_note,
  ].filter(n => n > 0);

  const pertinence = {
    ...pertinenceRaw,
    score_global: notesArr.length > 0
      ? Math.round(notesArr.reduce((a, b) => a + b, 0) / notesArr.length * 10) / 10
      : 0
  };

  // --- Offre ---
  const data = parseOffre(offreItems[i] || {});
  console.log(`Offre ${i+1} - name: "${data.name || '(non trouvé)'}"`);

  // --- Source scraping ---
  const traitementItem = traitementItems[i]?.json
    || sourceItems[i]?.json
    || {};
  const urlAAP = traitementItem.urlAAP || null;
  const idweb  = traitementItem.cle_dce || null;
  console.log(`urlAAP ${i+1}: ${urlAAP}`);

  // --- PDF ---
  let pdfBase64 = null;

  if (urlAAP) {
    try {
      console.log(`⬇️ Téléchargement PDF ${i+1}: ${urlAAP}`);
      const response = await this.helpers.httpRequest({
        method: 'GET',
        url: urlAAP,
        encoding: 'arraybuffer',
        returnFullResponse: true,
        timeout: 60000,
        headers: {
          'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36',
          'Accept': 'application/pdf,*/*',
        }
      });
      const bodyBuf = Buffer.from(response.body);
      const magic = bodyBuf.slice(0, 4).toString('ascii');
      console.log(`Magic: "${magic}", taille: ${bodyBuf.length}`);
      if (magic === '%PDF') {
        pdfBase64 = bodyBuf.toString('base64');
        console.log(`✓ Vrai PDF téléchargé - ${pdfBase64.length} chars`);
      } else {
        console.log(`❌ Pas un PDF valide - réponse HTML probablement`);
      }
    } catch(e) {
      console.log(`❌ Erreur téléchargement PDF: ${e.message}`);
    }
  }

  if (!pdfBase64) {
    const pdfTextItem = pdfItems[i];
    const texteSource = pdfTextItem?.json?.text || null;
    if (texteSource) {
      pdfBase64 = generatePdfFromText(texteSource);
      console.log(`✓ PDF généré depuis texte extrait - ${pdfBase64.length} chars`);
    } else {
      console.log(`⚠️ Aucun texte PDF disponible pour offre ${i+1}`);
    }
  }

  const pdfFilename = data.name
    ? `MarchesSec_${data.name.substring(0, 30).replace(/\s+/g, '_')}_${idweb || 'doc'}.pdf`
    : (idweb ? `MarchesSec_${idweb}.pdf` : null);

  // --- Valeurs nettoyées ---
  let expectedRevenue = Number(data.expected_revenue) || null;
  let buId = data.business_unit_id ? Number(data.business_unit_id) : null;

  const parseId = (val) => {
    if (!val || val === "" || val === "null") return null;
    const num = Number(val);
    return isNaN(num) ? null : num;
  };

  const urlOffre = traitementItem.urlDetail || data.website || null;

  const lead = {
    name:              data.name || traitementItem.objet || null,
    contact_name:      data.contact_name || traitementItem.acheteur || null,
    email_from:        data.email_from || null,
    phone:             data.phone || null,
    mobile:            data.phone || null,
    function:          data.function || null,
    email_cc:          data.email_cc || null,
    street:            data.street || null,
    street2:           data.street2 || null,
    city:              data.city || null,
    zip:               data.zip || null,
    company_name:      data.company_name || traitementItem.acheteur || null,
    website:           urlOffre,
    date_deadline:     data.date_deadline || traitementItem.dateCloture || null,
    probability:       50,
    expected_revenue:  expectedRevenue,
    country_id:        75,
    source_id:         11,
    user_id:           2,
    team_id:           1,
    partner_id:        1,
    business_unit_id:  buId,
    offre_id:          parseId(data.offre_id),
    sub_offre_id:      parseId(data.sous_offre_id),
    Mode_de_livraison: data.Mode_de_livraison,
    piste_source_id:   pisteSourceId ? Number(pisteSourceId) : null,
    pertinence:        pertinence,
    pdf_base64:        pdfBase64,
    pdf_filename:      pdfFilename,
  };

  console.log(`\n📊 LEAD ${i+1}:`);
  console.log(`  name: ${lead.name || '❌ NULL'}`);
  console.log(`  contact_name: ${lead.contact_name || '❌ NULL'}`);
  console.log(`  expected_revenue: ${lead.expected_revenue ?? '❌ NULL'}`);
  console.log(`  business_unit_id: ${lead.business_unit_id ?? '❌ NULL'}`);
  console.log(`  PDF: ${lead.pdf_base64 ? '✅ OUI (' + lead.pdf_base64.length + ' chars)' : '❌ NULL'}`);
  console.log(`  Score: ${lead.pertinence.score_global}`);

  results.push(lead);
}

console.log(`\n✅ ${results.length} leads construits`);
return [{ json: { offers: results } }];

const allItems = $input.all();

// ==================== 1. Séparer historique et offres ====================
const wonItems = allItems.filter(i => i.json?.partner_id);

const nouvellesOffres = allItems.filter(i => {
  const text = i.json?.text || '';
  return text.includes('=== NOUVEAU MARCHÉ À ÉVALUER ===');
});

// ==================== 2. Résumé compact historique ====================
const totalCA = wonItems.reduce((sum, i) => sum + (i.json.expected_revenue || 0), 0);
const avgCA = Math.round(totalCA / (wonItems.length || 1));

const parOffre = {};
for (const item of wonItems) {
  const cat = item.json.offre_id || 'Autre';
  if (!parOffre[cat]) parOffre[cat] = { count: 0, totalCA: 0 };
  parOffre[cat].count++;
  parOffre[cat].totalCA += item.json.expected_revenue || 0;
}

const parClient = {};
for (const item of wonItems) {
  const client = item.json.partner_id || '';
  parClient[client] = (parClient[client] || 0) + 1;
}
const clientsRecurrents = Object.entries(parClient)
  .filter(([, count]) => count > 1)
  .sort((a, b) => b[1] - a[1])
  .slice(0, 8)
  .map(([nom, count]) => `${nom} (${count}x)`)
  .join(', ');

const resumeCategories = Object.entries(parOffre)
  .sort((a, b) => b[1].count - a[1].count)
  .map(([cat, data]) => `  - ${cat}: ${data.count} projets, CA moy. ${Math.round(data.totalCA / data.count).toLocaleString('fr')}€`)
  .join('\n');

const revenues = wonItems.map(i => i.json.expected_revenue || 0).sort((a, b) => a - b);
const minCA = revenues[0] || 0;
const maxCA = revenues[revenues.length - 1] || 0;

const historique = `=== HISTORIQUE MARCHÉS GAGNÉS STUDIA (${wonItems.length} projets) ===
CA total: ${Math.round(totalCA).toLocaleString('fr')}€ | CA moyen: ${avgCA.toLocaleString('fr')}€
Fourchette: ${minCA.toLocaleString('fr')}€ → ${maxCA.toLocaleString('fr')}€

Répartition par offre:
${resumeCategories}

Clients récurrents: ${clientsRecurrents}`;

// ==================== 3. Un item par offre ====================
if (nouvellesOffres.length === 0) {
  return [{ json: { text: `${historique}\n\n=== AUCUNE NOUVELLE OFFRE ===` } }];
}

return nouvellesOffres.map((item, index) => {
  const text = item.json.text || '';
  const marker = '=== NOUVEAU MARCHÉ À ÉVALUER ===';
  const jsonPart = text.slice(text.indexOf(marker) + marker.length).trim();

  const texteComplet = `${historique}

=== NOUVEAU MARCHÉ À ÉVALUER ===
${jsonPart}`;

  return {
    json: {
      text: texteComplet,
      offre_index: index + 1,
      offre_name: item.json.offre_name || `Offre ${index + 1}`
    }
  };
});

// Loop over input items and add a new field called 'myNewField' to the JSON of each one
for (const item of $input.all()) {
  item.json.myNewField = 1;
}

return $input.all();

const allItems = $input.all();
let historique = "";
let configIA = {};
let marchés = [];

for (const item of allItems) {
  const json = item.json;

  // 1. Item avec texte (historique)
  if (json.text && json.text.includes("HISTORIQUE MARCHÉS GAGNÉS")) {
    historique = json.text;
  }

  // 2. Item avec config IA (structure: body.config_ia)
  if (json.body?.config_ia) {
    configIA = json.body.config_ia;
  }

  // 3. Item avec pdfText (marché)
  if (json.pdfText) {
    marchés.push({
      source: "pdfText",
      cle_dce: json.cle_dce || null,
      isValid: json.isValid || false,
      filterReason: json.filterReason || null,
      contenu: json.pdfText
    });
  }
}

// ==================== PRÉPARER TEXTE HISTORIQUE + CONFIG (partagé) ====================
let texteHistoriqueConfig = `=== HISTORIQUE ===\n${historique || "Non fourni"}\n\n`;
texteHistoriqueConfig += `=== CRITÈRES IA ===\n`;

if (configIA.criteres && configIA.criteres.length > 0) {
  const criteresRemplis = configIA.criteres.filter(c => 
    c.nom || c.description || c.pertinence_forte_si
  );

  if (criteresRemplis.length > 0) {
    criteresRemplis.forEach((critere, index) => {
      texteHistoriqueConfig += `Critère ${index + 1}: ${critere.nom || "Non nommé"}\n`;
      if (critere.description) texteHistoriqueConfig += `  Description: ${critere.description}\n`;
      if (critere.pertinence_forte_si) texteHistoriqueConfig += `  Pertinence forte si: ${critere.pertinence_forte_si}\n`;
    });
  } else {
    texteHistoriqueConfig += `Aucun critère IA configuré (utiliser les règles standard)\n`;
  }
} else {
  texteHistoriqueConfig += `Aucun critère IA configuré (utiliser les règles standard)\n`;
}

// ==================== CRÉER UN ITEM PAR MARCHÉ ====================
const results = [];

if (marchés.length === 0) {
  console.log("⚠️ Aucun marché détecté");
  return [{
    json: {
      text: texteHistoriqueConfig + "\n=== AUCUN MARCHÉ À ÉVALUER ===\n",
      cle_dce: null,
      nombre_marchés: 0
    }
  }];
}

marchés.forEach((marche, index) => {
  // Texte complet pour CE marché uniquement
  let texteMarche = texteHistoriqueConfig;
  texteMarche += `\n=== MARCHÉ À ÉVALUER ===\n`;

  if (marche.cle_dce) texteMarche += `Clé DCE: ${marche.cle_dce}\n`;
  if (marche.isValid !== undefined) texteMarche += `Validé: ${marche.isValid}\n`;
  if (marche.filterReason) texteMarche += `Raison: ${marche.filterReason}\n`;

  if (marche.contenu) {
    // Garder le contenu complet (pas de troncature pour le LLM)
    texteMarche += `\nContenu du marché:\n${marche.contenu}\n`;
  }

  console.log(`✓ Marché ${index + 1}/${marchés.length} préparé : ${marche.cle_dce}`);

  results.push({
    json: {
      text: texteMarche,
      cle_dce: marche.cle_dce,
      isValid: marche.isValid,
