const html = $input.first().json.data;
const offres = [];

const regexTable = /<table class="consultation[^"]*">([\s\S]*?)<\/table>/g;
let match;

while ((match = regexTable.exec(html)) !== null) {
  const blocHtml = match[1];

  const cleMatch = blocHtml.match(/addToFavoris\('([^']+)'/);
  const cle_dce = cleMatch ? cleMatch[1] : null;
  if (!cle_dce) continue;

  const objetMatch = blocHtml.match(/class="objet"[^>]*>[\s\S]*?<div[^>]*>([^<]+)<\/div>/);
  const objet = objetMatch ? objetMatch[1].trim() : '';

  // ← FILTRE : ignorer les offres sans objet
  if (!objet) {
    console.log(`⚠️ Offre ignorée (objet vide) : cle_dce=${cle_dce}`);
    continue;
  }

  const refMatch = blocHtml.match(/<th colspan="4">([^<]+)<\/th>/);
  const reference = refMatch ? refMatch[1].trim() : '';

  const acheteurMatch = blocHtml.match(/<tr class="tr_pa[^"]*">[\s\S]*?<td colspan="5">([^<]+)/);
  const acheteur = acheteurMatch ? acheteurMatch[1].trim() : '';

  const dateMatch = blocHtml.match(/class="td_clot_date">([^<]+)/);
  const dateCloture = dateMatch ? dateMatch[1].trim() : '';

  // ← NOUVEAU : parser la date de clôture en format YYYY-MM-DD pour Odoo
  let dateDeadline = null;
  if (dateCloture) {
    const joursFr = {
      'lundi': 'Mon', 'mardi': 'Tue', 'mercredi': 'Wed',
      'jeudi': 'Thu', 'vendredi': 'Fri', 'samedi': 'Sat', 'dimanche': 'Sun'
    };
    const moisFr = {
      'janvier': '01', 'février': '02', 'mars': '03', 'avril': '04',
      'mai': '05', 'juin': '06', 'juillet': '07', 'août': '08',
      'septembre': '09', 'octobre': '10', 'novembre': '11', 'décembre': '12'
    };
    // Format : "mardi 19 janvier 2038 - 04:14 (...)"
    const dm = dateCloture.match(/(\d{1,2})\s+(\w+)\s+(\d{4})/);
    if (dm) {
      const jour  = dm[1].padStart(2, '0');
      const mois  = moisFr[dm[2].toLowerCase()] || '01';
      const annee = dm[3];
      dateDeadline = `${annee}-${mois}-${jour}`;
    }
  }

 const urlDetail = `https://www.marches-securises.fr/entreprise/?module=consultation%7Cdetails&cle_dce=${cle_dce}`;
const urlAAP    = `https://www.marches-securises.fr/entreprise/?module=script%7Cdl_la_s&cle_dce=${cle_dce}`;

  console.log(`✅ Offre : ${cle_dce} | ${objet.substring(0, 60)} | deadline: ${dateDeadline}`);

  offres.push({
    json: {
      cle_dce,
      objet,
      reference,
      acheteur,
      dateCloture,
      dateDeadline,   // ← format YYYY-MM-DD directement utilisable par Odoo
      urlDetail,
      urlAAP
    }
  });
}

console.log(`✅ ${offres.length} offres valides trouvées`);
return offres;

